<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\{AuthController,DashboardController,ProductController,CategoryController,CustomerController,OrderController};
Route::get('/',fn()=>redirect()->route('login'));
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'showLogin'])->name('login');Route::post('/login',[AuthController::class,'login'])->middleware('throttle:5,1')->name('login.submit');Route::get('/register',[AuthController::class,'showRegister'])->name('register');Route::post('/register',[AuthController::class,'register'])->middleware('throttle:5,1')->name('register.submit');});
Route::middleware('auth')->group(function(){Route::get('/dashboard',[DashboardController::class,'index'])->name('dashboard');Route::post('/logout',[AuthController::class,'logout'])->name('logout');Route::get('/productos',[ProductController::class,'index'])->name('products.index');Route::post('/productos',[ProductController::class,'store'])->name('products.store');Route::put('/productos/{product}',[ProductController::class,'update'])->name('products.update');Route::delete('/productos/{product}',[ProductController::class,'destroy'])->name('products.destroy');Route::get('/categorias',[CategoryController::class,'index'])->name('categories.index');Route::post('/categorias',[CategoryController::class,'store'])->name('categories.store');Route::put('/categorias/{category}',[CategoryController::class,'update'])->name('categories.update');Route::delete('/categorias/{category}',[CategoryController::class,'destroy'])->name('categories.destroy');Route::get('/clientes',[CustomerController::class,'index'])->name('customers.index');Route::post('/clientes',[CustomerController::class,'store'])->name('customers.store');Route::put('/clientes/{customer}',[CustomerController::class,'update'])->name('customers.update');Route::delete('/clientes/{customer}',[CustomerController::class,'destroy'])->name('customers.destroy');Route::get('/pedidos',[OrderController::class,'index'])->name('orders.index');Route::post('/pedidos',[OrderController::class,'store'])->name('orders.store');Route::patch('/pedidos/{order}',[OrderController::class,'update'])->name('orders.update');});

Route::get('/tienda/{mype:slug}', [\App\Http\Controllers\ShopController::class,'show'])->name('shop.show');

Route::middleware('auth')->post('/mi-empresa/logo', [\App\Http\Controllers\BusinessBrandingController::class, 'update'])->name('business.logo.update');
